EXPLAIN ANALYZE SELECT * FROM orders WHERE user_id = 7 ORDER BY created_at DESC LIMIT 20;
-- Seq Scan / Full Table Scan 이 보이면 인덱스를 못 쓰고 있다
-- rows 추정치와 실제가 크게 다르면 통계가 낡았다

// 나쁨: 주문 100개면 쿼리 101번
for (const o of orders) o.user = await db.user(o.userId);

// 좋음: 한 번에
const users = await db.usersByIds([...new Set(orders.map((o) => o.userId))]);
